import * as backend from './backend.js';
import {escape,safeURL,toast,dialogEvents,readPreference,writePreference,courseCard,postCard,shareButton,popupClass} from './ui.js';
import {sanitizeRichHTML} from './richtext.js';
dialogEvents();
const menu=document.querySelector('.menu-btn'),nav=document.querySelector('#navlinks');
menu?.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav?.classList.contains('open')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.focus();}});
let allCourses=[],allPosts=[],selected='All';
function filterCourses(){const q=(document.querySelector('#course-search')?.value||'').toLowerCase();document.querySelectorAll('[data-course-card]').forEach(c=>{c.hidden=!(c.textContent.toLowerCase().includes(q)&&(selected==='All'||c.dataset.category===selected));});const grid=document.querySelector('#course-grid');if(grid){let notice=grid.querySelector('.empty');if(!notice){notice=document.createElement('p');notice.className='empty';notice.textContent='No classes match. Try another search.';grid.append(notice);}notice.hidden=!!grid.querySelector('[data-course-card]:not([hidden])');}}
document.querySelector('#course-search')?.addEventListener('input',filterCourses);
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{selected=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});filterCourses();}));
document.querySelector('#journal-search')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('#journal-grid .card').forEach(c=>c.hidden=!c.textContent.toLowerCase().includes(q));});
function settingsApply(s){if(!s)return;const headline=document.querySelector('[data-headline]');if(headline&&s.headline)headline.textContent=s.headline;document.querySelectorAll('[data-intro]').forEach(x=>{if(s.intro)x.textContent=s.intro;});document.querySelectorAll('[data-email]').forEach(x=>{if(/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s.email)){x.textContent=s.email;x.href='mailto:'+s.email;}});document.querySelectorAll('[data-whatsapp]').forEach(x=>{if(/^\d{10,15}$/.test(s.whatsapp)){const old=new URL(x.href);x.href='https://wa.me/'+s.whatsapp+old.search;}});}
async function loadPublic(){
 if(!backend.configured)return;
 try{
 const [courses,posts,settings]=await Promise.all([backend.list('classes',{publicOnly:true}),backend.list('posts',{publicOnly:true}),backend.get('content','public')]);
 allCourses=courses.sort((a,b)=>(a.order||0)-(b.order||0));allPosts=posts.sort((a,b)=>String(b.date).localeCompare(String(a.date)));settingsApply(settings);
 // Connected collections are authoritative, including intentionally empty collections.
 for(const [id,values,render] of [['course-grid',allCourses,courseCard],['featured-courses',allCourses.slice(0,3),courseCard],['journal-grid',location.pathname.endsWith('index.html')||location.pathname==='/'?allPosts.slice(0,3):allPosts,postCard]]){const el=document.getElementById(id);if(el)el.innerHTML=values.map(render).join('')||'<p class="empty">New content is being prepared. Please check back.</p>';}
 filterCourses();
 const tid=document.querySelector('#testimonial-grid')||document.querySelector('#home-testimonials');if(tid){const stories=await backend.list('testimonials',{publicOnly:true});tid.innerHTML=(tid.id==='home-testimonials'?stories.slice(0,3):stories).map(t=>`<a href="${escape(safeURL(t.image||t.url,{image:true}))}" target="_blank" rel="noopener"><img src="${escape(safeURL(t.image||t.url,{image:true}))}" alt="${escape(t.alt||'Student feedback screenshot')}" loading="lazy"></a>`).join('')||'<p>No published student stories yet.</p>';}
 const courseId=document.querySelector('#course-reviews')?.dataset.course;if(courseId){const c=allCourses.find(x=>x.id===courseId);if(c){document.querySelector('[data-course-description]').textContent=c.description||c.pageDesc||'';document.querySelector('[data-course-fee]').textContent=String(c.fee||'Ask Gracy').split(' · ')[0];document.querySelector('[data-checkout]').href=safeURL(c.checkout||c.selarLink);document.querySelector('.course-aside img').src=safeURL(c.image||c.flyerUrl,{image:true});document.querySelector('h1').textContent=c.title||c.pageTitle;}else{document.querySelector('[data-checkout]').removeAttribute('href');document.querySelector('[data-checkout]').textContent='This class is currently unavailable';}}
 await liveDetail();await loadReviews();enhanceMotion();scheduleCampaign();
 }catch{toast('Live content could not be loaded. Showing the saved academy pages.');}
}
async function liveDetail(){const id=new URLSearchParams(location.search).get('id');const article=document.querySelector('#live-article');if(article){const original=!!article.dataset.slug;const p=allPosts.find(x=>x.id===id||x.slug===article.dataset.slug);article.innerHTML=p?`<p class="eyebrow">${escape(p.category)} · ${escape(p.date)}</p>${original?'':`<h1>${escape(p.title)}</h1><p>${escape(p.excerpt)}</p>`}<img class="article-image" src="${escape(safeURL(p.image,{image:true}))}" alt="${escape(p.title)}"><div class="article-body prose">${p.bodyHtml?sanitizeRichHTML(p.bodyHtml):String(p.body||'').split('\n\n').map(s=>'<p>'+escape(s)+'</p>').join('')}</div><a class="text-link" href="/journal.html">← All stories</a>`:'<h1>Story unavailable.</h1><p>This article may be unpublished or removed.</p><a class="btn" href="/journal.html">Back to the journal</a>';if(p){document.querySelectorAll('.page-tools [data-share]').forEach(b=>{b.dataset.shareTitle=p.title;b.dataset.share=location.href;});if(!original){const canonical=document.querySelector('link[rel=canonical]');if(canonical)canonical.href=location.href;}const discussion=document.querySelector('#article-discussion');if(discussion){discussion.dataset.post=p.id;discussion.querySelector('form').dataset.post=p.id;loadComments();}if(original){document.querySelector('.page-intro h1').textContent=p.title;document.querySelector('.page-intro>p:last-child').textContent=p.excerpt;}document.title=p.title+' | ISew with Gracy';document.querySelector('meta[name="description"]').content=p.excerpt;}}
const el=document.querySelector('#live-course');if(el){const c=allCourses.find(x=>x.id===id);el.innerHTML=c?`<div class="course-layout"><div><p class="eyebrow">${escape(c.duration)}</p><h1>${escape(c.title)}</h1><p>${escape(c.description)}</p><p class="fee">${escape(c.fee)}</p>${shareButton(c.title,location.href)}<a class="btn" href="${escape(safeURL(c.checkout))}" target="_blank" rel="noopener noreferrer">Enrol through Selar ↗</a></div><img class="portrait" src="${escape(safeURL(c.image,{image:true}))}" alt="${escape(c.title)}"></div>`:'<h1>Class unavailable.</h1><a class="btn" href="/courses.html">Explore classes</a>';if(c)document.title=c.title+' | ISew with Gracy';}}
async function loadReviews(){const el=document.querySelector('#course-reviews');if(!el)return;try{const reviews=await backend.list('reviews',{publicOnly:true});const filtered=reviews.filter(r=>r.classId===el.dataset.course);if(filtered.length)el.innerHTML=filtered.map(r=>`<div class="admin-card"><strong>${escape(r.name)}</strong><p aria-label="${escape(r.rating)} out of 5 stars">${'★'.repeat(Math.min(5,Math.max(1,Number(r.rating)||1)))}</p><p>${escape(r.comment)}</p></div>`).join('');}catch{}}
for(const [selector,kind] of [['#enquiry-form','enquiries'],['#review-form','reviews']])document.querySelector(selector)?.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,v=Object.fromEntries(new FormData(f)),status=f.querySelector('[data-form-status]'),b=f.querySelector('[type="submit"]');if(v.website){status.textContent='Unable to submit.';return;}b.disabled=true;status.textContent='Sending securely…';try{const data=kind==='reviews'?{name:v.name.trim(),comment:v.comment.trim(),rating:Number(v.rating),classId:f.dataset.course}:{name:v.name.trim(),email:v.email.trim(),course:v.course,message:v.message.trim(),consent:true};await backend.submit(kind,data);f.reset();status.textContent=kind==='reviews'?'Thank you. Your review is awaiting approval.':'Thank you. Your enquiry has been sent to the academy.';}catch(err){status.textContent=err.message;}finally{b.disabled=false;}});
// Only suggest installation after the browser confirms it can install this PWA.
let installEvent=null;const installModal=document.querySelector('#install-modal');
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;document.querySelector('#install-confirm').hidden=false;if(!readPreference('isew-install-dismissed')&&!matchMedia('(display-mode: standalone)').matches&&!navigator.standalone)setTimeout(()=>document.querySelector('#install-bar').hidden=false,12000);});
document.querySelectorAll('[data-install]').forEach(x=>x.addEventListener('click',()=>installModal.showModal()));
document.querySelector('#install-confirm')?.addEventListener('click',async()=>{if(!installEvent)return;await installEvent.prompt();await installEvent.userChoice;installEvent=null;document.querySelector('#install-confirm').hidden=true;document.querySelector('#install-bar').hidden=true;installModal.close();});
document.querySelector('#install-dismiss')?.addEventListener('click',()=>{document.querySelector('#install-bar').hidden=true;writePreference('isew-install-dismissed','1');});
window.addEventListener('appinstalled',()=>{document.querySelector('#install-bar').hidden=true;installEvent=null;toast('The academy is now on your home screen.');});
async function scheduleCampaign(){try{const items=await backend.list('popups',{publicOnly:true});const now=Date.now(),eligible=items.filter(p=>p.enabled&&(!p.startsAt||Date.parse(p.startsAt)<=now)&&(!p.endsAt||Date.parse(p.endsAt)>=now)&&(!p.page||p.page==='all'||location.pathname===p.page)).sort((a,b)=>(b.priority||0)-(a.priority||0));const p=eligible.find(x=>{const last=Number(readPreference('isew-popup-'+x.id)||0);return !last||now-last>Math.max(1,Number(x.frequencyDays)||7)*86400000;});if(!p)return;setTimeout(()=>{if(document.querySelector('dialog[open]'))return;const modal=document.querySelector('#campaign-modal');modal.className='modal campaign-card '+popupClass(p.design);document.querySelector('#campaign-title').textContent=p.title;document.querySelector('#campaign-message').textContent=p.message;const a=document.querySelector('#campaign-link');a.textContent=p.buttonLabel||'Explore classes ↗';a.href=safeURL(p.url||'/courses.html');modal.showModal();modal.addEventListener('close',()=>writePreference('isew-popup-'+p.id,String(Date.now())),{once:true});},Math.max(3,Math.min(120,Number(p.delaySeconds)||12))*1000);}catch{}}
if('serviceWorker' in navigator&&location.protocol==='https:')navigator.serviceWorker.register('/sw.js').catch(()=>{});
loadPublic();
if(!backend.configured&&(location.pathname.endsWith('/article.html')||location.pathname.endsWith('/class.html')))liveDetail();
// Sharing always uses the item's own URL, with a copy-link fallback.
document.addEventListener('click',async event=>{const b=event.target.closest('[data-share]');if(!b)return;const url=new URL(b.dataset.share||location.href,location.origin).href,title=b.dataset.shareTitle||document.title;try{if(navigator.share){await navigator.share({title,url});return;}if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(url);toast('Link copied. Ready to share.');return;}openShareDialog(url,title);}catch(err){if(err.name!=='AbortError')openShareDialog(url,title);}});
function openShareDialog(url,title){const d=document.querySelector('#share-modal');document.querySelector('#share-link').value=url;document.querySelector('#share-whatsapp').href='https://wa.me/?text='+encodeURIComponent(title+' '+url);document.querySelector('#share-email').href='mailto:?subject='+encodeURIComponent(title)+'&body='+encodeURIComponent(url);d.showModal();document.querySelector('#share-link').select();}
document.querySelector('#copy-share-link')?.addEventListener('click',async()=>{const f=document.querySelector('#share-link');try{await navigator.clipboard.writeText(f.value);toast('Link copied.');}catch{f.select();toast('Select and copy the link to share.');}});
function enhanceMotion(){if(!('IntersectionObserver' in window)||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target);}});},{threshold:.08});document.querySelectorAll('.section-head,.step,.value,.card,.split,.home-stories,.cta').forEach(el=>{el.classList.add('reveal');observer.observe(el);});}
enhanceMotion();
const progress=document.querySelector('#reading-progress');if(progress)window.addEventListener('scroll',()=>{const available=document.documentElement.scrollHeight-innerHeight;progress.value=available>0?Math.round(scrollY/available*100):0;},{passive:true});
async function loadComments(){const section=document.querySelector('#article-discussion');if(!section)return;const id=section.dataset.post||new URLSearchParams(location.search).get('id');if(!id)return;section.dataset.post=id;const form=section.querySelector('form');form.dataset.post=id;if(!backend.configured)return;try{const items=await backend.list('comments',{publicOnly:true});const approved=items.filter(x=>x.postId===id).sort((a,b)=>(a.createdAt?.seconds||0)-(b.createdAt?.seconds||0));document.querySelector('#article-comments').innerHTML=approved.map(c=>`<article class="comment-card"><div class="comment-avatar" aria-hidden="true">${escape(String(c.name).trim().slice(0,1).toUpperCase())}</div><div><strong>${escape(c.name)}</strong><p>${escape(c.comment)}</p></div></article>`).join('')||'<p class="status">Be the first to add a thoughtful note.</p>';document.querySelector('#comment-count').textContent=approved.length+' published '+(approved.length===1?'comment':'comments');}catch{document.querySelector('#comment-count').textContent='Comments are temporarily unavailable.';}}
document.querySelector('#comment-form')?.addEventListener('submit',async event=>{event.preventDefault();const form=event.target,v=Object.fromEntries(new FormData(form)),status=form.querySelector('[data-form-status]'),button=form.querySelector('[type="submit"]');if(v.website)return;button.disabled=true;status.textContent='Sending your comment…';try{if(!form.dataset.post)throw new Error('Open a published article to leave a comment.');await backend.submit('comments',{postId:form.dataset.post,name:v.name.trim(),comment:v.comment.trim(),consent:true});form.reset();status.textContent='Thank you. Your comment will appear after approval.';}catch(err){status.textContent=err.message;}finally{button.disabled=false;}});
loadComments();
